import httpx

def check(url):
    try:
        httpx.get(url, timeout=2.0).raise_for_status()
        return "ok"
    except httpx.HTTPStatusError as e:
        return f"status {e.response.status_code} from {e.request.url.path}"
    except httpx.TimeoutException as e:
        return f"timeout: {type(e).__name__}"
    except httpx.RequestError as e:
        return f"request failed: {type(e).__name__}"

print(check("https://httpbin.org/get"))         # ok
print(check("https://httpbin.org/status/500"))  # status 500 from /status/500
print(check("https://httpbin.org/delay/5"))     # timeout: ReadTimeout
print(check("ftp://example.com"))               # request failed: UnsupportedProtocol
print(issubclass(httpx.ConnectError, httpx.RequestError))  # True

import httpx

calls = []

def handler(request: httpx.Request) -> httpx.Response:
    calls.append((request.method, request.url.path))
    if request.url.path == "/users/1":
        return httpx.Response(200, json={"id": 1, "name": "Ada"})
    if request.url.path == "/flaky":
        raise httpx.ConnectError("boom", request=request)
    return httpx.Response(404, json={"error": "not found"})

def get_name(client, user_id):
    r = client.get(f"/users/{user_id}")
    return r.json()["name"] if r.is_success else None

client = httpx.Client(base_url="https://api.test", transport=httpx.MockTransport(handler))
print(get_name(client, 1), get_name(client, 2))   # Ada None
try:
    client.get("/flaky")
except httpx.ConnectError as e:
    print("ConnectError:", e)                     # ConnectError: boom
print(calls)  # [('GET', '/users/1'), ('GET', '/users/2'), ('GET', '/flaky')]

import httpx

class RefreshingToken(httpx.Auth):
    def __init__(self):
        self.token = "expired"
    def auth_flow(self, request):
        request.headers["Authorization"] = f"Bearer {self.token}"
        response = yield request             # send and get the response back
        if response.status_code == 401:
            self.token = "fresh"             # pretend we refreshed it
            request.headers["Authorization"] = f"Bearer {self.token}"
            yield request                    # retry once

def handler(request):
    ok = request.headers["Authorization"] == "Bearer fresh"
    return httpx.Response(200 if ok else 401, json={"ok": ok})

log = []
client = httpx.Client(
    transport=httpx.MockTransport(handler), auth=RefreshingToken(),
    event_hooks={"response": [lambda r: log.append(r.status_code)]})
print(client.get("https://api.test/me").json())   # {'ok': True}
print(log)                                       # [401, 200]

import time
import httpx

class RetryTransport(httpx.BaseTransport):
    def __init__(self, inner, retries=3, statuses=(429, 503)):
        self.inner, self.retries, self.statuses = inner, retries, statuses
    def handle_request(self, request):
        for attempt in range(self.retries + 1):
            response = self.inner.handle_request(request)
            if response.status_code not in self.statuses or attempt == self.retries:
                return response
            response.close()                    # release the connection
            time.sleep(0.05 * 2 ** attempt)     # exponential backoff
    def close(self):
        self.inner.close()

attempts = []
def flaky(request):
    attempts.append(1)
    return httpx.Response(503 if len(attempts) < 3 else 200, text="done")

with httpx.Client(transport=RetryTransport(httpx.MockTransport(flaky))) as c:
    r = c.get("https://api.test/job")
print(r.status_code, r.text, len(attempts))     # 200 done 3
